@CrossOrigin
@RestController
@RequestMapping("/TerminationQuery")
public class TerminationQueryRestController extends BaseSpringRestController {
	
	public TerminationQueryRestController( TerminationService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Termination using a UUID
     * @param		UUID terminationId
     * @return		Termination
     */    
    @GetMapping("/load")
    public Termination load( @RequestParam(required=true) UUID terminationId ) {
    	Termination entity = null;

    	try {  
    		entity = service.getTermination( new TerminationFetchOneSummary( terminationId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Termination using Id " + terminationId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Termination business objects
     * @return		Set<Termination>
     */
    @GetMapping("/")
    public List<Termination> loadAll() {                
    	List<Termination> terminationList = null;
        
    	try {
            // load the Termination
            terminationList = service.getAllTermination();
            
            if ( terminationList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Terminations" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Terminations ", exc );
        	return null;
        }

        return terminationList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Termination termination = null;
    protected TerminationService service = null;
    private static final Logger LOGGER = Logger.getLogger(TerminationQueryRestController.class.getName());
    
}
